from requests.exceptions import HTTPError
from .connection import Connection
from ..exceptions import DeviceNotAvailable


class ServerApi(object):
    SUPPORTED_VERSION = 'v1'
    ATTENUATORS_PATH = '/{api_version}/attenuators'
    LOCATION_PATH = '{location}'
    PROFILE_PATH = '{location}/profile'
    ATTENUATION_PATH = '{location}/profile/{attenuator_port}/attenuation'

    def __init__(self, server_ip, server_port=8080):
        # TODO: future improvement- add check for server sanity
        self.location = None
        self.connection = Connection(server_ip, server_port)
        self.attenuators_path = self.ATTENUATORS_PATH.format(api_version=self.SUPPORTED_VERSION)

    def setup_attenuator(self, vendor, location, model=None):
        self.location = location
        self._check_device_available()
        self._post_attenuation_profile(vendor, model)

    def _check_device_available(self):
        location_path = self.LOCATION_PATH.format(location=self.location)

        location_endpoint = '/'.join([self.attenuators_path, location_path])
        try:
            self.connection.get(location_endpoint)
        except HTTPError:
            raise DeviceNotAvailable('Device is not available under given location')

    def _post_attenuation_profile(self, vendor, model):
        profile_path = self.PROFILE_PATH.format(location=self.location)
        profile_schema = {'vendor': vendor, 'model': model}
        profile_endpoint = '/'.join([self.attenuators_path, profile_path])

        response = self.connection.post(endpoint=profile_endpoint, data=profile_schema)
        response.raise_for_status()

    def set_attenuation(self, attenuator_port, attenuation_value):
        attenuation_schema = {'value': attenuation_value}

        attenuation_path = self.ATTENUATION_PATH.format(
            location=self.location,
            attenuator_port=attenuator_port
        )
        attenuation_endpoint = '/'.join([self.attenuators_path, attenuation_path])
        response = self.connection.post(endpoint=attenuation_endpoint, data=attenuation_schema)
        response.raise_for_status()

    def get_current_attenuation(self, attenuator_port):
        attenuation_path = self.ATTENUATION_PATH.format(
            location=self.location,
            attenuator_port=attenuator_port
        )
        attenuation_endpoint = '/'.join([self.attenuators_path, attenuation_path])
        response = self.connection.get(endpoint=attenuation_endpoint)
        response.raise_for_status()
        attenuation_value = response.json()['value']
        return attenuation_value
